    /**
     * Method to retrieve the Claim via an ClaimPrimaryKey.
     * @param 	id Long
     * @return 	Claim
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Claim handle( FindClaimQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getClaimId() );
    }
    
    /**
     * Method to retrieve a collection of all Claims
     *
     * @param	query	FindAllClaimQuery 
     * @return 	List<Claim> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Claim> handle( FindAllClaimQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindClaim,
 * but only if the id matches
 *
 * @param		entity	Claim
 */
	protected void emitFindClaim( Claim entity ) {
		LOGGER.info("handling emitFindClaim" );
		
	    queryUpdateEmitter.emit(FindClaimQuery.class,
	                            query -> query.getFilter().getClaimId().equals(entity.getClaimId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllClaim
	 * 
	 * @param		entity	Claim
	 */
	protected void emitFindAllClaim( Claim entity ) {
		LOGGER.info("handling emitFindAllClaim" );
		
	    queryUpdateEmitter.emit(FindAllClaimQuery.class,
	                            query -> true,
	                            entity);
	}

